class Solution {
public:
    int findShortestSubArray(vector<int>& nums) {
        unordered_map<int,int> count, first, last;
        int degree = 0;
        int n = (int)nums.size();
        for (int i = 0; i < n; i++) {
            int v = nums[i];
            count[v]++;
            if (first.find(v) == first.end()) first[v] = i;
            last[v] = i;
            if (count[v] > degree) degree = count[v];
        }
        int ans = n;
        for (auto& p : count) {
            if (p.second == degree) {
                int v = p.first;
                int len = last[v] - first[v] + 1;
                if (len < ans) ans = len;
            }
        }
        return ans;
    }
};
